<script setup>
import {computed,ref,watch} from 'vue'
import {landscapeSteps,landscapes} from '../services/local-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
const props=defineProps({mode:{type:String,default:'hill'}})
const mode=ref(props.mode),preset=ref('valley'),seed=ref(7),temperature=ref(4),cooling=ref(.9),tenure=ref(3),width=ref(2),start=ref(1),step=ref(0),costs=ref(landscapes.valley.costs.slice()),custom=ref(costs.value.join(', ')),error=ref('')
const trace=computed(()=>Array.from(landscapeSteps({costs:costs.value,start:start.value,mode:mode.value,seed:seed.value,temperature:temperature.value,cooling:cooling.value,tenure:tenure.value,width:width.value,budget:24})))
const state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),resetKey=computed(()=>JSON.stringify([mode.value,costs.value,start.value,seed.value,temperature.value,cooling.value,tenure.value,width.value]))
watch(resetKey,()=>step.value=0)
watch(preset,()=>{const p=landscapes[preset.value];costs.value=p.costs.slice();start.value=p.start;custom.value=p.costs.join(', ');error.value=''})
const x=i=>35+i*570/(costs.value.length-1),y=v=>220-155*(v-Math.min(...costs.value))/(Math.max(...costs.value)-Math.min(...costs.value)||1)
const path=computed(()=>costs.value.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' '))
const costLabel=v=>Math.abs(v)>=1000?Number(v).toExponential(0):String(v)
const message=computed(()=>{
 const s=state.value
 if(s.phase==='start')return 'Khởi tạo. Mỗi vị trí chỉ nối với hai vị trí kề. Chi phí nhỏ hơn là tốt hơn.'
 if(s.phase==='local')return 'Dừng: Không có láng giềng tốt hơn. Đây là điểm dừng cục bộ đối với phép lân cận đã chọn.'
 if(s.phase==='blocked')return 'Dừng: Mọi láng giềng đều bị cấm và không phá kỷ lục. Có thể đổi độ dài danh sách hoặc khởi động lại.'
 if(s.phase==='budget')return 'Hết 24 vòng quan sát. Kết quả tốt nhất đã lưu không phải chứng nhận tối ưu toàn cục.'
 if(s.phase==='pool')return 'Gom các láng giềng của toàn bộ chùm, loại vị trí trùng rồi xếp theo chi phí và chỉ số.'
 if(s.phase==='select')return 'Chọn những vị trí tốt nhất từ tập con chung. Hai vị trí được chọn có thể đến từ cùng một cha.'
 if(s.phase==='probability')return `Δ = ${s.delta}. Nhiệt độ ${s.T.toFixed(3)}, xác suất ${s.probability.toFixed(4)}, số ngẫu nhiên ${s.draw.toFixed(4)}. ${s.accepted?'Chấp nhận':'Từ chối'} đề xuất.`
 if(s.phase==='admissible')return s.aspiration?'Phá lệ tabu vì đề xuất tốt hơn kỷ lục toàn cục.':'Chọn láng giềng tốt nhất được phép, kể cả khi chi phí tăng.'
 if(s.phase==='reject')return 'Giữ trạng thái hiện tại vì phép thử xác suất từ chối đề xuất.'
 if(s.phase==='move')return 'Cập nhật vị trí hiện tại và chỉ thay kỷ lục khi tìm được chi phí nhỏ hơn.'
 return 'Xét láng giềng theo chi phí tăng dần. Khi bằng nhau, ưu tiên chỉ số nhỏ hơn.'
})
function apply(){try{const a=custom.value.split(/[,;\s]+/).filter(Boolean).map(Number);Array.from(landscapeSteps({costs:a,start:Math.min(start.value,a.length-1)}));costs.value=a;start.value=Math.min(start.value,a.length-1);error.value=''}catch(e){error.value=e.message}}
</script>
<template><section class="math-lab local-landscape" aria-label="Mô phỏng tìm kiếm trên không gian chi phí"><div class="local-settings"><label>Thuật toán<select v-model="mode"><option value="hill">Leo đồi</option><option value="anneal">Tôi luyện mô phỏng</option><option value="beam">Chùm cục bộ</option><option value="tabu">Tabu</option></select></label><label>Không gian mẫu<select v-model="preset"><option v-for="(p,id) in landscapes" :key="id" :value="id">{{ p.title }}</option></select></label><label>Vị trí đầu<select v-model.number="start"><option v-for="(_,i) in costs" :key="i" :value="i">{{ i }}</option></select></label><label v-if="mode==='anneal'">Hạt giống<select v-model.number="seed"><option v-for="i in [1,7,23,42]" :key="i" :value="i">{{ i }}</option></select></label><label v-if="mode==='anneal'">Nhiệt độ đầu<select v-model.number="temperature"><option v-for="i in [.5,2,4,10]" :key="i" :value="i">{{ i }}</option></select></label><label v-if="mode==='anneal'">Hệ số làm nguội<select v-model.number="cooling"><option v-for="i in [.5,.9,.99]" :key="i" :value="i">{{ i }}</option></select></label><label v-if="mode==='tabu'">Số trạng thái nhớ<select v-model.number="tenure"><option v-for="i in [1,2,3,5]" :key="i">{{ i }}</option></select></label><label v-if="mode==='beam'">Độ rộng chùm<select v-model.number="width"><option v-for="i in [1,2,3]" :key="i">{{ i }}</option></select></label></div><SimulationControls v-model="step" :max="trace.length-1" :reset-key="resetKey"/><svg class="landscape-svg" viewBox="0 0 640 275" role="img" aria-label="Đường chi phí rời rạc, trạng thái hiện tại và tốt nhất"><text x="12" y="20">Chi phí</text><path :d="path" class="landscape-line"/><g v-for="(v,i) in costs" :key="i"><circle :cx="x(i)" :cy="y(v)" :r="state.current===i?9:5" :class="{current:state.current===i,best:state.best===i,beam:mode==='beam'&&state.beam.includes(i)}"/><text v-if="costs.length<=10||i%2===0" :x="x(i)" :y="y(v)-15" text-anchor="middle">{{ costLabel(v) }}</text><text :x="x(i)" y="250" text-anchor="middle">{{ i }}</text></g></svg><div class="local-summary"><span>Hiện tại {{ state.current }} · C = {{ costs[state.current] }}</span><span>Tốt nhất {{ state.best }} · C = {{ costs[state.best] }}</span><span v-if="mode==='tabu'">Tabu từ cũ đến mới: {{ state.tabu.join(' → ') }}</span><span v-if="mode==='beam'">Chùm: {{ state.beam.join(', ') }}</span></div><p class="local-status" role="status" aria-live="polite">{{ message }}</p><details><summary>Dữ liệu và quy ước</summary><p>Vị trí đánh số từ 0. Chùm ban đầu lấy vị trí đầu, vị trí cuối rồi các vị trí biên/giữa khác cho đến đủ độ rộng. Danh sách tabu chứa trạng thái vừa đến, có độ dài hữu hạn. Thay tham số sẽ đưa mô phỏng về bước đầu.</p><label>Chi phí theo thứ tự vị trí<input v-model="custom" aria-label="Dãy chi phí tự nhập"></label><button type="button" @click="apply">Dùng dãy chi phí</button><p v-if="error" role="alert">{{ error }}</p></details><SearchTraceCode name="landscapeSteps" :phase="state.phase"/></section></template>
<style scoped>
.local-landscape{min-width:0}.local-settings{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.local-landscape label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.local-landscape :is(select,input,button){min-width:0;max-width:100%;min-height:44px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);padding:8px;font:inherit}.local-landscape button{cursor:pointer}.landscape-svg{display:block;width:100%;height:auto;margin:20px 0;background:var(--paper)}.landscape-svg text{font:15px var(--font-ui);fill:var(--ink)}.landscape-line{fill:none;stroke:var(--ink-2);stroke-width:1.5}.landscape-svg circle{stroke:var(--ink-2);fill:var(--paper);stroke-width:1.5}.landscape-svg circle.beam{fill:var(--tim-soft);stroke:var(--tim);stroke-width:4}.landscape-svg circle.best{stroke:var(--xanh);stroke-width:4}.landscape-svg circle.current{fill:var(--tim)}@media(max-width:480px){.landscape-svg text{font-size:26px}.landscape-svg text:first-child{font-size:23px}}.local-summary{display:flex;flex-wrap:wrap;gap:8px;font:var(--fs-small)/1.7 var(--font-ui)}.local-summary span{padding:8px;background:var(--paper);border:1px solid var(--rule);border-radius:var(--radius)}.local-status{border-left:3px solid var(--tim);padding:12px;background:var(--tim-soft)}summary{min-height:44px;cursor:pointer}:is(select,input,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}
</style>
